with scored as (select *, avg(balance) over (partition by customer_id, account_type order by opened_date, id rows between 6 preceding and 1 preceding) as balance_avg_6_prior, lag(balance, 2) over (partition by status order by opened_date, id) as prev_balance from accounts) select id, customer_id, account_type, opened_date, balance_avg_6_prior, prev_balance, case when account_type rlike '^(CREDIT|CHECKING)$' then 'GROUP_B' when account_type rlike '^(SAVINGS|LOAN)$' then 'OTHER_ZONE' else 'GROUP_A' end as account_type_zone from scored order by customer_id nulls first;
